// Неравенства, прогрессии, функции и графики: +10 заданий на каждую тему.
import type { Template } from '../helpers'
import { c, N, T, th, pick, rnd, fx, frac, type B } from './bi'

const q = (p: B, tail: string): B => [`${p[0]} ${tail}`, p[1].endsWith(':') ? `${p[1]} ${tail}` : `${tail.replace(/\.$/, '')} ${p[1]}`]
const lin = (k: number, v = 'x') => (k === 0 ? '' : ` ${k < 0 ? '-' : '+'} ${Math.abs(k) === 1 ? '' : Math.abs(k)}${v}`)
const num = (k: number) => (k === 0 ? '' : ` ${k < 0 ? '-' : '+'} ${Math.abs(k)}`)
const tri = (p: number, r: number) => `x^2${lin(-(p + r))}${num(p * r)}`
const two = (): [number, number] => { let p = rnd(-6, 6); if (p === 0) p = 2; let r = rnd(-6, 6); while (r === p || r === -p || r === 0) r = rnd(-6, 6); return [Math.min(p, r), Math.max(p, r)] }
const iv = (a: string, b: string, l = '(', r = ')') => `$${l}${a};\\ ${b}${r}$`
const INF = '+\\infty', MINF = '-\\infty'

const INEQ: B = ['Решите неравенство', 'теңсіздігін шешіңіз.']
const CNT: B = ['Сколько целых решений имеет неравенство', 'теңсіздігінің неше бүтін шешімі бар?']
const SUMI: B = ['Найдите сумму целых решений неравенства', 'теңсіздігінің бүтін шешімдерінің қосындысын табыңыз.']
const DOM: B = ['Найдите область определения функции', 'функциясының анықталу облысын табыңыз.']
const RNG: B = ['Найдите множество значений функции', 'функциясының мәндер жиынын табыңыз.']

